cd /workspace && python3 - <<'PYEOF'
import sys, json, random
sys.path.insert(0,'/tmp'); sys.path.insert(0,'/workspace/submission')
from adaptive2 import run_one
rng=random.Random(7)
links=[(i,i+1) for i in range(9)]+[(0,5),(2,7),(1,8),(3,9)]
cmds=[{"op":"load","n":10,"links":[[u,v,rng.choice([3,5,8,10])] for (u,v) in links],"bookings":[]}]
rev=0; now=0; ids=['pa','pb']
for i in range(255):
    r=i%8
    if r==0:
        now+=rng.randint(0,10); rev+=1; cmds.append({"op":"advance","time":now})
    elif r in (1,2):
        cmds.append({"op":"prepare","id":ids[i%2],"owner":"o","window":[now,now+10],"period":10,
                     "participants":[[0,1],[3,2],[7,1]],"envelope":[[l,1] for l in range(13)],"rev":rev})
    elif r==3: cmds.append({"op":"commit","id":ids[i%2],"owner":"o","rev":rev})
    elif r==4: cmds.append({"op":"cancel","id":ids[i%2],"owner":"o","rev":rev})
    elif r==5: cmds.append({"op":"edit","rev":rev,"changes":[[0,10]],"force":False})
    elif r==6: cmds.append({"op":"audit","at":[now,now+3,now]})
    else: cmds.append({"op":"about"})
reps=run_one(cmds)
for i in range(9,18):
    print(i, json.dumps(cmds[i])[:110])
    print("   ->", json.dumps(reps[i])[:120])
PYEOF
